import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

const readProjectFile = (path) => readFile(new URL(`../../${path}`, import.meta.url), 'utf8');

test('backend image keeps the Prisma client generated during its build before pruning dev dependencies', async () => {
  const dockerfile = await readProjectFile('backend/Dockerfile');

  assert.doesNotMatch(
    dockerfile,
    /npm prune --omit=dev[\s\S]*?\.\/node_modules\/\.bin\/prisma generate/,
    'Prisma Client is generated by npm run build; regenerating it after npm prune makes publishing fragile.',
  );
});

test('Docker publishing uses the documented production API fallback when GitHub environment variables are absent', async () => {
  const workflow = await readProjectFile('.github/workflows/docker-deploy.yml');

  const apiFallbacks = workflow.match(/NEXT_PUBLIC_API_URL=\$\{\{ vars\.NEXT_PUBLIC_API_URL \|\| secrets\.NEXT_PUBLIC_API_URL \|\| 'https:\/\/api\.jcbexchange\.com\/api' \}\}/g) ?? [];
  assert.equal(apiFallbacks.length, 2, 'Frontend and admin portal must both have the API fallback.');
  assert.doesNotMatch(workflow, /Validate Frontend public build variables/);
  assert.doesNotMatch(workflow, /Validate Admin Portal public build variables/);
});

test('Dokploy compose consumes the images published by this repository instead of building source on the VPS', async () => {
  const compose = await readProjectFile('docker-compose.prod.yml');

  assert.doesNotMatch(compose, /^\s+build:/m);
  assert.match(compose, /ghcr\.io\/\$\{GHCR_OWNER:-webitof-web-agency\}\/jcbexchange-backend:latest/);
  assert.match(compose, /ghcr\.io\/\$\{GHCR_OWNER:-webitof-web-agency\}\/jcbexchange-frontend:latest/);
  assert.match(compose, /ghcr\.io\/\$\{GHCR_OWNER:-webitof-web-agency\}\/jcbexchange-admin-portal:latest/);
});
